css:
html{-webkit-text-size-adjust:100%}
body{margin:0;background:#F9F4EC}
.bt-vz{--navy:#004877;--ink:#1d1e1f;--cream:#F9F4EC;--sand:#F3E9D9;--sky:#3C96E7;--line:rgba(0,72,119,.16);--mut:rgba(0,72,119,.66);--body:rgba(29,30,31,.78);--serif:"Bodoni Moda","Bodoni MT",Didot,Georgia,serif;--sans:"Jost","Century Gothic",Futura,"Helvetica Neue",Arial,sans-serif;--gut:clamp(20px,4vw,56px);--ease:cubic-bezier(.2,.7,.2,1);display:block;background:var(--cream);color:var(--ink);font-family:var(--sans);font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased;text-align:left;overflow-wrap:break-word}
.bt-vz *,.bt-vz *::before,.bt-vz *::after{box-sizing:border-box}
.bt-vz a{color:inherit;text-decoration:none}
.bt-vz p{margin:0}
.bt-vz ul,.bt-vz ol{list-style:none;margin:0;padding:0}
.bt-vz img{display:block;max-width:100%}
.bt-vz button{font-family:inherit;color:inherit}
.bt-vz svg{width:18px;height:18px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round}
.bt-vz [hidden]{display:none!important}
.bt-vz a:focus-visible,.bt-vz button:focus-visible,.bt-vz input:focus-visible,.bt-vz label:focus-visible{outline:2px solid var(--sky);outline-offset:2px}
.bt-vz h1,.bt-vz h2,.bt-vz h3,.bt-vz .bt-vz-name{font-optical-sizing:none;font-variation-settings:"opsz" 30}
.bt-vz .bt-wrap{max-width:1600px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.bt-vz .bt-kicker{display:flex;align-items:center;gap:14px;font-size:12.5px;line-height:1;font-weight:500;letter-spacing:.24em;text-transform:uppercase;color:var(--navy);margin-bottom:22px}
.bt-vz .bt-kicker::before{content:"";width:40px;height:1px;background:currentColor}
.bt-vz .bt-btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:54px;padding:0 26px;font-family:var(--sans);font-size:12.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;text-align:center;border:1px solid var(--navy);background:var(--navy);color:#fff;cursor:pointer;transition:background .5s var(--ease),color .5s var(--ease)}
.bt-vz .bt-btn:hover{background:transparent;color:var(--navy)}
.bt-vz .bt-btn-line{background:transparent;color:var(--navy)}
.bt-vz .bt-btn-line:hover{background:var(--navy);color:#fff}
.bt-vz .bt-link{display:inline-flex;align-items:center;gap:10px;font-size:12px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--navy);border-bottom:1px solid currentColor;padding-bottom:5px}
.bt-vz .bt-link svg{width:14px;height:14px}

/* heading */
.bt-vz .bt-vz-head{padding-top:clamp(36px,4vw,60px);padding-bottom:clamp(28px,3vw,44px)}
.bt-vz .bt-crumbs{display:flex;gap:10px;font-size:12px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;color:var(--mut);margin-bottom:clamp(24px,3vw,40px)}
.bt-vz .bt-crumbs a:hover{color:var(--navy)}
.bt-vz .bt-vz-head-in{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:clamp(20px,5vw,96px);align-items:end}
.bt-vz h1{font-family:var(--serif);font-weight:400;font-size:clamp(40px,5.2vw,76px);line-height:1.02;letter-spacing:-.015em;margin:0;text-wrap:balance}
.bt-vz h1 em{font-style:italic;color:var(--navy)}
.bt-vz .bt-intro{color:var(--body);max-width:58ch}

/* app */
.bt-vz .bt-vz-app{position:relative;padding-bottom:clamp(64px,8vw,112px)}
.bt-vz .bt-vzr{position:absolute;left:0;top:0;width:1px;height:1px;opacity:0;pointer-events:none;margin:0}
.bt-vz .bt-vz-grid{display:grid;grid-template-columns:minmax(0,1fr) clamp(340px,29vw,440px);gap:clamp(20px,2.4vw,40px);align-items:start}
.bt-vz .bt-vz-view{position:sticky;top:96px;min-width:0}
.bt-vz .bt-vz-stage{position:relative;aspect-ratio:1600/893;overflow:hidden;background:#cfc8bc;box-shadow:0 50px 80px -56px rgba(29,30,31,.7)}
.bt-vz .bt-vz-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transition:opacity .6s var(--ease)}
.bt-vz .bt-vzr1:checked~.bt-vz-grid .bt-vz-img1,.bt-vz .bt-vzr2:checked~.bt-vz-grid .bt-vz-img2,.bt-vz .bt-vzr3:checked~.bt-vz-grid .bt-vz-img3{opacity:1}
.bt-vz .bt-vz-canvas{position:absolute;inset:0;width:100%;height:100%;display:block;opacity:0;transition:opacity .5s var(--ease)}
.bt-vz .bt-ready .bt-vz-canvas{opacity:1}
.bt-vz .bt-vz-tag{position:absolute;left:0;top:0;z-index:2;background:rgba(17,18,19,.8);color:#fff;padding:12px 18px;font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase}
.bt-vz .bt-vz-deftag{display:none}
.bt-vz .bt-vzr1:checked~.bt-vz-grid .bt-vz-deftag1,.bt-vz .bt-vzr2:checked~.bt-vz-grid .bt-vz-deftag2,.bt-vz .bt-vzr3:checked~.bt-vz-grid .bt-vz-deftag3{display:inline}
.bt-vz .bt-on .bt-vz-tag-static{display:none}
.bt-vz .bt-vz-tag-live{display:none}
.bt-vz .bt-on .bt-vz-tag-live{display:block}
.bt-vz .bt-vz-rooms{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border:1px solid var(--ink);border-top:0}
.bt-vz .bt-vz-room{display:flex;align-items:center;justify-content:center;min-height:54px;font-size:12px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;cursor:pointer;background:#fff;border-left:1px solid var(--ink);transition:background .4s var(--ease),color .4s var(--ease)}
.bt-vz .bt-vz-room:first-child{border-left:0}
.bt-vz .bt-vzr1:checked~.bt-vz-grid .bt-vz-room1,.bt-vz .bt-vzr2:checked~.bt-vz-grid .bt-vz-room2,.bt-vz .bt-vzr3:checked~.bt-vz-grid .bt-vz-room3{background:var(--ink);color:#fff}
.bt-vz .bt-vzr1:focus-visible~.bt-vz-grid .bt-vz-room1,.bt-vz .bt-vzr2:focus-visible~.bt-vz-grid .bt-vz-room2,.bt-vz .bt-vzr3:focus-visible~.bt-vz-grid .bt-vz-room3{outline:2px solid var(--sky);outline-offset:-3px}
.bt-vz .bt-vz-note{font-size:13.5px;line-height:1.55;color:rgba(29,30,31,.62);margin-top:16px;max-width:90ch}

/* panel */
.bt-vz .bt-vz-panel{background:#fff;border:1px solid var(--line);min-width:0}
.bt-vz .bt-vz-nojs{padding:26px;color:var(--body)}
.bt-vz .bt-vz-nojs a{color:var(--navy);border-bottom:1px solid var(--line)}
.bt-vz .bt-vz-controls{display:none}
.bt-vz .bt-on .bt-vz-controls{display:block}
.bt-vz .bt-on .bt-vz-nojs{display:none}
.bt-vz .bt-vz-sel{padding:24px 26px;border-bottom:1px solid var(--line);background:var(--sand)}
.bt-vz .bt-vz-look{font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--mut);margin-bottom:8px}
.bt-vz .bt-vz-name{font-family:var(--serif);font-size:32px;line-height:1.08}
.bt-vz .bt-vz-price{font-size:15px;color:var(--body);margin-top:8px}
.bt-vz .bt-vz-price b{font-family:var(--serif);font-weight:400;font-size:24px;color:var(--navy)}
.bt-vz .bt-vz-f{padding:20px 26px;border-bottom:1px solid var(--line)}
.bt-vz .bt-vz-fl{display:flex;justify-content:space-between;align-items:baseline;gap:12px;font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--mut);margin-bottom:12px}
.bt-vz .bt-vz-fl small{font-size:11px;letter-spacing:.08em;text-transform:none;color:rgba(29,30,31,.55)}
.bt-vz .bt-vz-search{display:block;width:100%;height:46px;border:1px solid var(--line);border-radius:0;background:#fff;padding:0 14px;font-family:var(--sans);font-size:16px;color:var(--ink);margin-bottom:12px}
.bt-vz .bt-vz-tiles{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;max-height:318px;overflow-y:auto;padding:2px;overscroll-behavior:contain}
.bt-vz .bt-vz-t{position:relative;display:block;padding:0;border:0;background:transparent;cursor:pointer;text-align:left;min-width:0}
.bt-vz .bt-vz-t img{width:100%;aspect-ratio:1;object-fit:cover;outline:1px solid var(--line);outline-offset:-1px;transition:transform .5s var(--ease)}
.bt-vz .bt-vz-t:hover img{transform:scale(1.05)}
.bt-vz .bt-vz-t span{display:block;font-size:12px;line-height:1.25;margin-top:6px;color:var(--body);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.bt-vz .bt-vz-t i{position:absolute;left:0;top:0;background:var(--navy);color:#fff;font-style:normal;font-size:8.5px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;padding:3px 5px}
.bt-vz .bt-vz-t[aria-pressed="true"] img{outline:3px solid var(--navy);outline-offset:-3px}
.bt-vz .bt-vz-t[aria-pressed="true"] span{color:var(--navy);font-weight:500}
.bt-vz .bt-vz-t.bt-off{opacity:.28;cursor:not-allowed}
.bt-vz .bt-vz-warn{font-size:13px;color:var(--body);margin-top:12px}
.bt-vz .bt-vz-opts{display:flex;flex-wrap:wrap;gap:8px}
.bt-vz .bt-vz-opt{min-height:44px;padding:0 16px;border:1px solid var(--line);background:#fff;font-size:13.5px;letter-spacing:.04em;cursor:pointer;transition:background .3s var(--ease),color .3s var(--ease),border-color .3s var(--ease)}
.bt-vz .bt-vz-opt:hover{border-color:var(--navy)}
.bt-vz .bt-vz-opt[aria-pressed="true"]{background:var(--navy);border-color:var(--navy);color:#fff}
.bt-vz .bt-vz-opt:disabled{opacity:.35;cursor:not-allowed}
.bt-vz .bt-vz-g{display:inline-flex;align-items:center;gap:10px}
.bt-vz .bt-vz-g::before{content:"";width:18px;height:18px;border-radius:50%;background:var(--g);box-shadow:inset 0 0 0 1px rgba(29,30,31,.25)}
.bt-vz .bt-vz-act{padding:22px 26px 26px;display:grid;gap:10px}
.bt-vz .bt-vz-act .bt-btn{width:100%}
.bt-vz .bt-busy .bt-vz-stage::after{content:"";position:absolute;right:16px;top:16px;z-index:3;width:18px;height:18px;border-radius:50%;border:2px solid rgba(255,255,255,.5);border-top-color:#fff;animation:btSpin .8s linear infinite}
@keyframes btSpin{to{transform:rotate(360deg)}}

/* how it works */
.bt-vz .bt-vz-how{background:var(--ink);color:var(--cream);padding-top:clamp(64px,8vw,112px);padding-bottom:clamp(64px,8vw,112px)}
.bt-vz .bt-vz-how .bt-kicker{color:var(--sand)}
.bt-vz .bt-vz-how h2{font-family:var(--serif);font-weight:400;font-size:clamp(34px,4.2vw,58px);line-height:1.06;margin:0 0 clamp(36px,4vw,56px)}
.bt-vz .bt-vz-how h2 em{font-style:italic;color:var(--sand)}
.bt-vz .bt-vz-steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:clamp(20px,3vw,56px);counter-reset:s}
.bt-vz .bt-vz-steps li{counter-increment:s;border-top:1px solid rgba(249,244,236,.22);padding-top:24px}
.bt-vz .bt-vz-steps li::before{content:"0" counter(s);display:block;font-family:var(--serif);font-size:44px;line-height:1;color:var(--sand);margin-bottom:18px}
.bt-vz .bt-vz-steps h3{font-family:var(--serif);font-weight:400;font-size:27px;line-height:1.15;margin:0 0 10px}
.bt-vz .bt-vz-steps p{font-weight:300;color:rgba(249,244,236,.78)}
.bt-vz .bt-vz-cta{display:flex;flex-wrap:wrap;gap:14px;margin-top:clamp(36px,4vw,56px)}
.bt-vz .bt-vz-how .bt-btn{background:var(--cream);border-color:var(--cream);color:var(--ink)}
.bt-vz .bt-vz-how .bt-btn:hover{background:transparent;color:var(--cream)}
.bt-vz .bt-vz-how .bt-btn-line{background:transparent;border-color:rgba(249,244,236,.5);color:var(--cream)}
.bt-vz .bt-vz-how .bt-btn-line:hover{background:var(--cream);color:var(--ink)}

@media (max-width:1100px){
.bt-vz .bt-vz-grid{grid-template-columns:minmax(0,1fr)}
.bt-vz .bt-vz-view{position:static}
.bt-vz .bt-vz-head-in{grid-template-columns:minmax(0,1fr);align-items:start}
.bt-vz .bt-vz-tiles{grid-template-columns:repeat(6,minmax(0,1fr))}
}
@media (max-width:760px){
.bt-vz{font-size:16.5px}
.bt-vz .bt-vz-view{position:sticky;top:60px;z-index:5;margin:0 calc(var(--gut) * -1);background:var(--cream)}
.bt-vz .bt-vz-note{display:none}
.bt-vz .bt-vz-room{min-height:44px;font-size:11px}
.bt-vz .bt-vz-tag{padding:8px 10px;font-size:9.5px;letter-spacing:.14em}
.bt-vz .bt-vz-tiles{grid-template-columns:repeat(4,minmax(0,1fr));max-height:250px}
.bt-vz .bt-vz-steps{grid-template-columns:minmax(0,1fr)}
.bt-vz .bt-vz-f,.bt-vz .bt-vz-sel,.bt-vz .bt-vz-act{padding-left:18px;padding-right:18px}
.bt-vz .bt-vz-cta .bt-btn{flex:1 1 220px}
}
@media (prefers-reduced-motion:reduce){.bt-vz *,.bt-vz *::before,.bt-vz *::after{transition-duration:.01ms!important;animation-duration:.01ms!important}}
